import{_ as n,l as o,o as e,c as i,v as t,p as s,x as r,d as p,i as h,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"农产品天气升水","description":"","frontmatter":{"title":"农产品天气升水","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ag-weather-premium.md","filePath":"quant/ag-weather-premium.md","lastUpdated":1789023840000}'),d={name:"quant/ag-weather-premium.md"};function m(A,a,u,c,_,B){const l=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="农产品天气升水" tabindex="-1">农产品天气升水 <a class="header-anchor" href="#农产品天气升水" aria-label="Permalink to &quot;农产品天气升水&quot;">​</a></h1><div class="epigraph"><p>生长季里，产量还没有收割出来，价格却已经在为尚未实现的干旱与热浪付保险费；这份保险费走在气象预报与作物评级前面，也会在预报兑现或证伪后迅速退潮。</p><footer>—— 天气与作物价格的经典对照见 Roll, Orange Juice and Weather, American Economic Review, 1984</footer></div><p>谷物与油籽的远期曲线在播种后、收割前，经常出现无法用库存便利收益单独解释的升水：市场为生长期天气支付选择权。Richard Roll 1984 年用冷冻浓缩橙汁期货说明，气象信息进入价格的速度可以快过当时被引用的「有效市场」叙事所能轻松消化的程度。今日玉米、大豆、小麦在北美生长季（大致六至八月）的天气市，把同一机制做成了年度循环：高温、降水、土壤墒情与作物评级一动，现货尚未减产，期权隐含波动与虚值看涨先动。它与 <a href="/quant/crack-spread">能源裂解</a> 同属商品实物约束，但状态变量是气象与单产，不是炼厂收率。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记收获期期货价格为 \\(F_t\\)，无天气风险时的「库存均衡」价格为 \\(F_t^{\\mathrm{inv}}\\)（由结转库存、需求弹性、仓储成本决定）。生长季升水可写成</p> \\[F_t = F_t^{\\mathrm{inv}} + \\mathrm{WP}_t, \\]<p>其中天气升水 \\(\\mathrm{WP}_t\\ge 0\\) 在关键物候窗口（授粉、灌浆）最大，收割后若单产落地，升水兑现为现货或退回。问题是识别：价格上涨有多少是真实的条件预期减产，有多少是风险溢价——即交易员为避免在干旱尾部做空而要求的额外补偿。欧式期权把二者混进隐含分布的右尾：减产使价格暴涨，虚值看涨变贵，形成商品特有的正向偏斜，与股票指数常见的负偏斜相反，见 <a href="/quant/vol-skew">Skew</a>。</p><p>天气不是隐藏信息交易。卫星、预报与 USDA 评级对所有人可见，但预报误差与局地对流使产量仍是随机的。把升水当成 <a href="/quant/pin">PIN</a> 那种知情概率，会用错微观结构模型：这里没有私有信息层级，有的是公共信号下的尾部保险。</p><h3 id="物候窗口决定升水的期限结构" tabindex="-1">物候窗口决定升水的期限结构 <a class="header-anchor" href="#物候窗口决定升水的期限结构" aria-label="Permalink to &quot;物候窗口决定升水的期限结构&quot;">​</a></h3><p>玉米授粉对高温与干旱最敏感，窗口只有数周；大豆结荚更长；小麦分冬小麦与春小麦，关键期不同。升水因此不是常数便利收益，而是日历上的确定性季节乘上当年的随机气象状态。同一月份在生长季与收获后，价格对同一张 2 米气温图的弹性完全不同。用全年样本估一个价格–气温回归，会把无弹性的月份稀释掉关键周的弹性。</p><p><span class="marginnote">「天气市」在交易俚语里常被滥用成任何一次天气相关的波动。可操作的定义是：关键物候期内，产量预期的修正主导价格发现，库存逻辑暂时让路。离开窗口，同样的热浪可能只影响需求侧电力，对谷物升水贡献很小。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>产量映射。</strong> 把气象场（降水、温度、蒸散、土壤湿度）经作物模型或经验响应函数映到单产，再经面积与需求弹性映到价格。一阶近似是</p> \\[\\Delta \\ln F \\approx -\\varepsilon^{-1}\\,\\Delta \\ln Y, \\]<p>\\(Y\\) 为产量，\\(\\varepsilon\\) 为需求价格弹性（短期很小，故产量几个百分点可以撬动很大价格）。非线性来自阈值：花期连续数日高温的损害远大于把同样度日均匀摊到一个月。这使天气升水具有期权剖面：轻度异常贡献有限，极端事件贡献跳跃。</p><p><strong>期权读取升水。</strong> 生长季近月期权的风险反转常偏向看涨；蝶式升水表示产量尾部被交易。隐含波动的期限结构在关键周之前隆起，收割后回落——这是季节性 Vega，不是 <a href="/quant/heston">Heston</a> 均值回复参数 \\(\\kappa\\) 的估计。用全年日历去校准一个无季节的随机波动模型，会把每年夏天的隆起误读成 vol-of-vol。更干净的做法是：把时间换成作物时钟（出苗后天数），再谈微笑动态。</p><p><strong>与天气衍生品分工。</strong> CME 的度日期货（HDD/CDD）对冲的是温度本身，谷物期货对冲的是产量与价格。二者相关但不完全：干旱可以高温，也可以在温度不极端时发生。用电力天气合约去对冲玉米，是相关交易，不是复制。Roll 的橙汁例子已经提示：价格对预报残差敏感，对「已经在预报里的气候」不敏感。</p><h3 id="报告日与预报日的事件窗" tabindex="-1">报告日与预报日的事件窗 <a class="header-anchor" href="#报告日与预报日的事件窗" aria-label="Permalink to &quot;报告日与预报日的事件窗&quot;">​</a></h3><p>USDA 供需报告、作物进度与评级，把连续气象压缩成离散跳。跳空发生在隔夜，连续对冲在日间失效，处理见 <a href="/quant/overnight-gap-hedge">隔夜跳空对冲</a>。预报更新则是日内连续流。事件研究应分开：报告窗用开盘跳，预报窗用高频；把它们混进同一个已实现方差，会让「天气升水」的实现波动不可解释。期权做市在报告前加宽报价、降低 Gamma 限额，等于把升水的跳跃部分当成不可 Delta 复制的残差，这与 <a href="/quant/discrete-hedge-error">离散对冲误差</a> 的跳跃项一致。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>升水存在，是因为产量尾部对商业空头（农民尚未收割完成、或已预售）和消费多头（饲料、加工）不对称。消费方更怕涨价断料，愿意为看涨尾部付费；投机资本提供保险，要求正的风险溢价。于是即使气象中性预期下，\\(F_t\\) 也可以高于「平均产量对应的价格」：凸性与保险把均值抬起。收获后信息落地，保险退潮，曲线可能出现季节性的实现负溢价——这不是模型算错，是期权到期。</p><p>库存缓冲决定升水幅度。结转库存高时，同样的干旱威胁被库存吸收，\\(\\mathrm{WP}_t\\) 小；库存紧时，天气期权的杠杆最大。这与能源裂解里「产能利用率高则裂解波动大」同构：都是实物期权在约束附近变凸。便利收益解释库存对曲线的水平，天气升水解释生长季对尚未入库产量的选择权，二者可加，不要互相替代。</p><h3 id="偏斜符号与股票期权相反" tabindex="-1">偏斜符号与股票期权相反 <a class="header-anchor" href="#偏斜符号与股票期权相反" aria-label="Permalink to &quot;偏斜符号与股票期权相反&quot;">​</a></h3><p>股票指数崩盘时现货下跌、隐含波动上升，负相关制造负偏斜。谷物减产时现货上涨、波动也上升，正相关制造正偏斜：虚值看涨贵。把股权 <a href="/quant/sabr">SABR</a> 的 \\(\\rho\\lt 0\\) 习惯直接贴到玉米上，Delta 会对错边。生长季结束、库存逻辑恢复后，偏斜可能减弱甚至随宏观风险回到更常见的商品形状。因此农产品微笑必须带作物日历，不能只用货币性 \\(k=\\ln(K/F)\\)。</p><p><span class="marginnote">卫星 NDVI 与土壤墒情现在几乎实时。升水并未消失，因为把植被指数译成最终单产仍有误差，且极端热害在指数里滞后。信息更快改变的是升水的高频更新，不是升水是否该存在。</span></p>',25)),(e(),s(E,null,{default:r(()=>[h(l,{id:"mermaid-69",class:"mermaid",graph:"flowchart%20TD%0A%20%20Met%5B%22%E6%B0%94%E8%B1%A1%E5%9C%BA%E4%B8%8E%E9%A2%84%E6%8A%A5%22%5D%20--%3E%20Yield%5B%22%E5%8D%95%E4%BA%A7%E5%93%8D%E5%BA%94%20%E9%9D%9E%E7%BA%BF%E6%80%A7%E9%98%88%E5%80%BC%22%5D%0A%20%20Phen%5B%22%E7%89%A9%E5%80%99%E7%AA%97%E5%8F%A3%22%5D%20--%3E%20Yield%0A%20%20Yield%20--%3E%20WP%5B%22%E5%A4%A9%E6%B0%94%E5%8D%87%E6%B0%B4%20WP%22%5D%0A%20%20Inv%5B%22%E7%BB%93%E8%BD%AC%E5%BA%93%E5%AD%98%22%5D%20--%3E%20WP%0A%20%20WP%20--%3E%20F%5B%22%E6%94%B6%E8%8E%B7%E6%9C%9F%E6%9C%9F%E8%B4%A7%20F%22%5D%0A%20%20WP%20--%3E%20Skew%5B%22%E6%AD%A3%E5%90%91%E5%81%8F%E6%96%9C%20%2F%20%E5%AD%A3%E8%8A%82%E6%80%A7%20Vega%22%5D%0A%20%20USDA%5B%22%E4%BE%9B%E9%9C%80%E4%B8%8E%E8%AF%84%E7%BA%A7%E8%B7%B3%22%5D%20--%3E%20F%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>全球种植带分散风险：美国干旱可被南美丰产对冲，升水是条件于其他半球尚未揭晓的。把单一产区气象直接映射到 CBOT 价格，忽略出口与争地（玉米–大豆面积替代）。转基因与农艺进步改变历史响应函数，用 1980 年代的度日弹性给今日定价会偏大。灌溉产区的天气 beta 小于旱作。</p><p>期权上，美式农产品期权含提前行权与交割选择，隐含波动不是纯欧式切片，无套利插值见 <a href="/quant/arb-free-iv">隐波插值</a>，但要先处理实物交割与转换因子。天气升水不是可滚动的常青因子：窗口一过，历史回测里的夏日 alpha 不能外推到十一月。不要用无季节的 Heston 五参数去「解释」每年一次的天气隆起，那是日历，不是随机方差的 \\(\\theta\\)。</p><p><span class="marginnote">Roll（1984）证明的是橙汁价格对天气信息的反应，不是给出一个可交易的「天气升水指数」。把 AER 论文写成今日玉米天气市的参数表，是年代与作物的双重错位。机制可迁移，弹性必须重估。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>天气升水是生长季里对尚未实现单产风险的保险费，叠加在库存决定的均衡价格之上。</li><li>物候窗口与阈值响应使升水呈期权剖面；库存越紧，凸性越大。</li><li>农产品生长季常现正偏斜与季节性 Vega，与股指负偏斜、无季节 Heston / SABR 习惯相反。</li><li>USDA 报告造成隔夜跳，预报造成日内修正；对冲与已实现波动应分窗。</li><li>升水在收割后消退，不是常青风险溢价；全球产区与农艺变化限制历史弹性。</li><li>出处：Roll, <em>Orange Juice and Weather</em>, AER, 1984；作物–价格弹性见农业经济学实务；波动率形状对照 Heston，1993 与 Hagan et al.，2002；对冲框架见 Hull。</li></ul>',6))])}const q=n(d,[["render",m]]);export{f as __pageData,q as default};
